CREATE TABLE IF NOT EXISTS bookkeeping_batch_runs (
  id INTEGER PRIMARY KEY,
  run_key TEXT NOT NULL UNIQUE,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  accounting_from TEXT NOT NULL,
  accounting_to TEXT NOT NULL,
  bank_from TEXT NOT NULL,
  bank_to TEXT NOT NULL,
  plan_hash TEXT NOT NULL CHECK(length(plan_hash) = 64),
  plan_json TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_events (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  event_type TEXT NOT NULL CHECK(event_type IN ('planned','approved','apply_started','final_checks','completed')),
  plan_hash TEXT NOT NULL CHECK(length(plan_hash) = 64),
  actor TEXT NOT NULL,
  detail_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_bookkeeping_batch_events_run ON bookkeeping_batch_events(run_id,id);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_item_attempts (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  action_key TEXT NOT NULL,
  evidence_hash TEXT NOT NULL CHECK(length(evidence_hash) = 64),
  outcome TEXT NOT NULL CHECK(outcome IN ('started','applied','failed','stale','duplicate')),
  error_text TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_bookkeeping_batch_item_attempts_run_action ON bookkeeping_batch_item_attempts(run_id,action_key,id);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_applied_links (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  action_key TEXT NOT NULL,
  document_id INTEGER REFERENCES documents(id),
  journal_entry_id INTEGER REFERENCES journal_entries(id),
  bank_transaction_id INTEGER REFERENCES bank_transactions(id),
  vat_preflight_id INTEGER,
  posting_rule_application_id INTEGER REFERENCES posting_rule_applications(id),
  purchase_application_id INTEGER,
  exception_id INTEGER REFERENCES exceptions(id),
  evidence_hash TEXT NOT NULL CHECK(length(evidence_hash) = 64),
  created_at TEXT NOT NULL,
  UNIQUE(run_id, action_key)
);
CREATE TABLE IF NOT EXISTS bookkeeping_batch_final_checks (
  id INTEGER PRIMARY KEY,
  run_id INTEGER NOT NULL REFERENCES bookkeeping_batch_runs(id),
  check_name TEXT NOT NULL CHECK(check_name IN ('audit_chain','trial_balance','reconciliation','vat')),
  ok INTEGER NOT NULL CHECK(ok IN (0,1)),
  detail_json TEXT NOT NULL,
  created_at TEXT NOT NULL,
  UNIQUE(run_id, check_name)
);
CREATE TRIGGER bookkeeping_batch_runs_no_update BEFORE UPDATE ON bookkeeping_batch_runs BEGIN SELECT RAISE(ABORT, 'bookkeeping batch runs are immutable'); END;
CREATE TRIGGER bookkeeping_batch_runs_no_delete BEFORE DELETE ON bookkeeping_batch_runs BEGIN SELECT RAISE(ABORT, 'bookkeeping batch runs are append-only'); END;
CREATE TRIGGER bookkeeping_batch_events_no_update BEFORE UPDATE ON bookkeeping_batch_events BEGIN SELECT RAISE(ABORT, 'bookkeeping batch events are append-only'); END;
CREATE TRIGGER bookkeeping_batch_events_no_delete BEFORE DELETE ON bookkeeping_batch_events BEGIN SELECT RAISE(ABORT, 'bookkeeping batch events are append-only'); END;
CREATE TRIGGER bookkeeping_batch_item_attempts_no_update BEFORE UPDATE ON bookkeeping_batch_item_attempts BEGIN SELECT RAISE(ABORT, 'bookkeeping batch item attempts are append-only'); END;
CREATE TRIGGER bookkeeping_batch_item_attempts_no_delete BEFORE DELETE ON bookkeeping_batch_item_attempts BEGIN SELECT RAISE(ABORT, 'bookkeeping batch item attempts are append-only'); END;
CREATE TRIGGER bookkeeping_batch_applied_links_no_update BEFORE UPDATE ON bookkeeping_batch_applied_links BEGIN SELECT RAISE(ABORT, 'bookkeeping batch applied links are immutable'); END;
CREATE TRIGGER bookkeeping_batch_applied_links_no_delete BEFORE DELETE ON bookkeeping_batch_applied_links BEGIN SELECT RAISE(ABORT, 'bookkeeping batch applied links are append-only'); END;
CREATE TRIGGER bookkeeping_batch_final_checks_no_update BEFORE UPDATE ON bookkeeping_batch_final_checks BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are immutable'); END;
CREATE TRIGGER bookkeeping_batch_final_checks_no_delete BEFORE DELETE ON bookkeeping_batch_final_checks BEGIN SELECT RAISE(ABORT, 'bookkeeping batch final checks are append-only'); END;
